package com.xdownload.mobile;
import org.junit.*;import static org.junit.Assert.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.util.concurrent.atomic.*;
public class HttpEngineTest{
 ServerSocket s;Thread server;volatile boolean stop;String url;File part;byte[] data=new byte[400000];AtomicInteger ranges=new AtomicInteger();volatile boolean ignore,html;
 @Before public void init()throws Exception{new java.util.Random(7).nextBytes(data);part=File.createTempFile("download",".part");s=new ServerSocket(0,64,InetAddress.getByName("127.0.0.1"));server=new Thread(()->{while(!stop)try(Socket socket=s.accept()){BufferedReader reader=new BufferedReader(new InputStreamReader(socket.getInputStream()));String first=reader.readLine(),line,range=null;while((line=reader.readLine())!=null&&!line.isEmpty())if(line.toLowerCase(java.util.Locale.ROOT).startsWith("range:"))range=line.substring(6).trim();int offset=0,end=data.length-1;boolean partial=range!=null&&!ignore;if(partial){ranges.incrementAndGet();String[] bounds=range.substring(6).split("-", -1);offset=Integer.parseInt(bounds[0]);if(!bounds[1].isEmpty())end=Integer.parseInt(bounds[1]);}String headers="HTTP/1.1 "+(partial?"206 Partial Content":"200 OK")+"\r\nContent-Type: "+(html?"text/html":"application/octet-stream")+"\r\nContent-Disposition: attachment; filename=\"sample.bin\"\r\nETag: \"v1\"\r\nAccept-Ranges: bytes\r\nContent-Length: "+(end-offset+1)+"\r\nConnection: close\r\n"+(partial?"Content-Range: bytes "+offset+"-"+end+"/"+data.length+"\r\n":"")+"\r\n";OutputStream out=socket.getOutputStream();out.write(headers.getBytes(java.nio.charset.StandardCharsets.US_ASCII));if(first!=null&&first.startsWith("GET"))out.write(data,offset,end-offset+1);out.flush();}catch(Exception ignored){}});server.start();url="http://127.0.0.1:"+s.getLocalPort()+"/file";}
 @After public void end()throws Exception{stop=true;s.close();server.join(2000);part.delete();ParallelEngine.clear(part);}
 HttpEngine.Observer obs(){return new HttpEngine.Observer(){public boolean proceed(){return true;}public void progress(long n,long t,String e,String m){}};}
 @Test public void probe()throws Exception{HttpEngine.Info i=HttpEngine.probe(url,true);assertEquals(data.length,i.size);assertEquals("sample.bin",i.name);assertTrue(i.ranges);}
 @Test public void actualTransfer()throws Exception{assertEquals(data.length,HttpEngine.download(url,true,part,"","",obs(),0));assertArrayEquals(data,Files.readAllBytes(part.toPath()));assertEquals(64,HttpEngine.sha256(part).length());}
 @Test public void actualResume()throws Exception{Files.write(part.toPath(),java.util.Arrays.copyOf(data,123456));HttpEngine.download(url,true,part,"\"v1\"","",obs(),0);assertEquals(1,ranges.get());assertArrayEquals(data,Files.readAllBytes(part.toPath()));}
 @Test public void ignoredRangeRestarts()throws Exception{ignore=true;Files.write(part.toPath(),new byte[400]);HttpEngine.download(url,true,part,"\"old\"","",obs(),0);assertArrayEquals(data,Files.readAllBytes(part.toPath()));}
 @Test public void noValidatorRestarts()throws Exception{Files.write(part.toPath(),new byte[400]);HttpEngine.download(url,true,part,"","",obs(),0);assertEquals(0,ranges.get());assertArrayEquals(data,Files.readAllBytes(part.toPath()));}
 @Test public void pause()throws Exception{AtomicBoolean go=new AtomicBoolean(true);long r=HttpEngine.download(url,true,part,"","",new HttpEngine.Observer(){public boolean proceed(){return go.get();}public void progress(long n,long t,String e,String m){if(n>0)go.set(false);}},0);assertEquals(-1,r);assertTrue(part.length()>0&&part.length()<data.length);}
 @Test public void noHtml()throws Exception{html=true;try{HttpEngine.download(url,true,part,"","",obs(),0);fail();}catch(IOException e){assertTrue(e.getMessage().contains("web page"));}}
 @Test public void httpsDefault()throws Exception{try{HttpEngine.validated(url,false);fail();}catch(IOException expected){}try{HttpEngine.validated("https://user:pass@example.com/a",false);fail();}catch(IOException expected){}assertFalse(HttpEngine.safeName("../../x").contains("/"));}
 @Test public void changedValidatorRejected()throws Exception{Files.write(part.toPath(),new byte[400]);try{HttpEngine.download(url,true,part,"\"old\"","",obs(),0);fail();}catch(IOException e){assertTrue(e.getMessage().contains("Remote file changed"));assertEquals(400,part.length());}}
 @Test public void mediaManifestIsNotFullVideo(){assertTrue(HttpEngine.manifest("video.m3u8","text/plain"));assertTrue(HttpEngine.manifest("index","application/dash+xml"));assertFalse(HttpEngine.manifest("video.mp4","video/mp4"));assertEquals("Videos",HttpEngine.category("video.mkv","application/octet-stream"));assertEquals("Music",HttpEngine.category("track.flac","application/octet-stream"));}
 @Test public void parallelValidatedRanges()throws Exception{data=new byte[5*1024*1024];new java.util.Random(33).nextBytes(data);assertEquals(data.length,ParallelEngine.transfer(url,true,part,obs(),3));assertEquals(3,ranges.get());assertArrayEquals(data,Files.readAllBytes(part.toPath()));}
 @Test public void parallelRejectsUnhonoredRanges()throws Exception{data=new byte[5*1024*1024];ignore=true;try{ParallelEngine.transfer(url,true,part,obs(),3);fail();}catch(IOException expected){assertFalse(part.exists());}assertEquals(data.length,HttpEngine.download(url,true,part,"","",obs(),0));assertArrayEquals(data,Files.readAllBytes(part.toPath()));}
 @Test public void checkpointReusesValidatedBytes()throws Exception{data=new byte[5*1024*1024];new java.util.Random(81).nextBytes(data);AtomicBoolean go=new AtomicBoolean(true);long result=ParallelEngine.transfer(url,true,part,new HttpEngine.Observer(){public boolean proceed(){return go.get();}public void progress(long n,long total,String e,String m){if(n>0)go.set(false);}},3);assertEquals(-1,result);assertTrue(ParallelEngine.hasCheckpoint(part));assertTrue(ParallelEngine.savedBytes(part)>0);long before=ParallelEngine.savedBytes(part);AtomicLong first=new AtomicLong(-1);assertEquals(data.length,ParallelEngine.transfer(url,true,part,new HttpEngine.Observer(){public boolean proceed(){return true;}public void progress(long n,long total,String e,String m){first.compareAndSet(-1,n);}},2));assertEquals(before,first.get());assertArrayEquals(data,Files.readAllBytes(part.toPath()));assertFalse(ParallelEngine.hasCheckpoint(part));}

 @Test public void sixteenAndThirtyTwoRangesByteExact()throws Exception{data=new byte[8*1024*1024+37];new java.util.Random(94).nextBytes(data);for(int connections:new int[]{16,32}){part.delete();ParallelEngine.clear(part);ranges.set(0);assertEquals(data.length,ParallelEngine.transfer(url,true,part,obs(),connections));assertEquals(connections,ranges.get());assertArrayEquals(data,Files.readAllBytes(part.toPath()));assertFalse(ParallelEngine.hasCheckpoint(part));}}

 @Test public void dynamicRangesByteExactAndCheckpoint()throws Exception{data=new byte[9*1024*1024+17];new java.util.Random(199).nextBytes(data);AtomicBoolean go=new AtomicBoolean(true);long paused=ParallelEngine.transfer(url,true,part,new HttpEngine.Observer(){public boolean proceed(){return go.get();}public void progress(long n,long t,String e,String m){if(n>0)go.set(false);}},3,true);assertEquals(-1,paused);assertTrue(DynamicRanges.hasLayout(part));long bytes=ParallelEngine.savedBytes(part);assertTrue(bytes>0);AtomicLong first=new AtomicLong(-1);assertEquals(data.length,ParallelEngine.transfer(url,true,part,new HttpEngine.Observer(){public boolean proceed(){return true;}public void progress(long n,long t,String e,String m){first.compareAndSet(-1,n);}},2,true));assertEquals(bytes,first.get());assertArrayEquals(data,Files.readAllBytes(part.toPath()));assertFalse(ParallelEngine.hasCheckpoint(part));}
 @Test public void dynamicPartitionSplitsOnlyUnwrittenTail()throws Exception{long m=1024L*1024;assertEquals(-1,DynamicRanges.splitPoint(0,m,0));assertEquals(5*m,DynamicRanges.splitPoint(0,8*m,2*m));HttpEngine.Info info=new HttpEngine.Info("sample","application/octet-stream",12*m,"\"v1\"","",true);DynamicRanges.Layout layout=new DynamicRanges.Layout(part,info,url);layout.init(2);DynamicRanges.Piece a=layout.claim(true),b=layout.claim(true);assertNotNull(a);assertNotNull(b);a.done=m;DynamicRanges.Piece c=layout.claim(true);assertNotNull(c);assertEquals(3,layout.parts.size());layout.validate();assertTrue(layout.coverage()[0]>0);assertEquals(0,layout.coverage()[15]);assertTrue(DynamicRanges.hasLayout(part));}
 @Test public void dynamicRejectsInvalidRange()throws Exception{data=new byte[5*1024*1024];ignore=true;try{ParallelEngine.transfer(url,true,part,obs(),3,true);fail();}catch(IOException expected){assertFalse(part.exists());assertFalse(ParallelEngine.hasCheckpoint(part));}}

 @Test public void directTransferRejectsUnexpectedEncoding()throws Exception{try(ServerSocket bad=new ServerSocket(0,2,InetAddress.getByName("127.0.0.1"))){Thread server=new Thread(()->{try(Socket client=bad.accept()){BufferedReader reader=new BufferedReader(new InputStreamReader(client.getInputStream()));String line;while((line=reader.readLine())!=null&&!line.isEmpty()){}client.getOutputStream().write(("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Encoding: gzip\r\nContent-Length: 4\r\nConnection: close\r\n\r\nABCD").getBytes(java.nio.charset.StandardCharsets.US_ASCII));client.getOutputStream().flush();}catch(IOException ignored){}});server.start();try{HttpEngine.download("http://127.0.0.1:"+bad.getLocalPort()+"/file",true,part,"","",obs(),0);fail("Encoded bytes accepted");}catch(IOException expected){assertTrue(expected.getMessage().contains("encoding"));}finally{server.join(3000);}}}

 @Test public void contradictoryResumeLengthPreservesExistingBytes()throws Exception{byte[] prefix={1,2,3,4};Files.write(part.toPath(),prefix);try(ServerSocket bad=new ServerSocket(0,2,InetAddress.getByName("127.0.0.1"))){bad.setSoTimeout(5000);Thread responder=new Thread(()->{try(Socket c=bad.accept()){c.setSoTimeout(5000);BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream()));String l;while((l=r.readLine())!=null&&!l.isEmpty()){}c.getOutputStream().write(("HTTP/1.1 206 Partial Content\r\nContent-Type: application/octet-stream\r\nContent-Range: bytes 4-7/8\r\nETag: \"v1\"\r\nContent-Length: 5\r\nConnection: close\r\n\r\nABCDE").getBytes(java.nio.charset.StandardCharsets.US_ASCII));c.getOutputStream().flush();}catch(IOException ignored){}});responder.start();try{HttpEngine.download("http://127.0.0.1:"+bad.getLocalPort()+"/file",true,part,"\"v1\"","",obs(),0);fail("Conflicting length accepted");}catch(IOException expected){assertTrue(expected.getMessage().contains("range"));assertArrayEquals(prefix,Files.readAllBytes(part.toPath()));}finally{responder.join(6000);}}}
}
